using System;using System.Data;using System.Data.SqlClient;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;
namespace AshkanJobCenter.UI{public class MatchingPage:UserControl{DataGridView grid;ComboBox jobs;public MatchingPage(){BackColor=Theme.Background;var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=60,Padding=new Padding(5)};jobs=new ComboBox{Width=360,DropDownStyle=ComboBoxStyle.DropDownList};var dt=Database.Query("SELECT Id,Title FROM Jobs WHERE Status='Open' ORDER BY Id DESC");jobs.DataSource=dt;jobs.DisplayMember="Title";jobs.ValueMember="Id";var run=Ui.Button(L.Fa?"محاسبه تطبیق":"Run matching");run.Click+=(s,e)=>Run();top.Controls.Add(Ui.Label(L.Fa?"فرصت شغلی":"Job"));top.Controls.Add(jobs);top.Controls.Add(run);grid=Ui.Grid();Controls.Add(grid);Controls.Add(top);grid.BringToFront();if(dt.Rows.Count>0)Run();}void Run(){if(jobs.SelectedValue==null)return;int id=Convert.ToInt32(jobs.SelectedValue);var job=Database.Query("SELECT Title,City,Category,Description FROM Jobs WHERE Id=@i",new SqlParameter("@i",id));if(job.Rows.Count==0)return;string city=Convert.ToString(job.Rows[0]["City"]), text=(Convert.ToString(job.Rows[0]["Title"])+" "+Convert.ToString(job.Rows[0]["Category"])+" "+Convert.ToString(job.Rows[0]["Description"])).ToLowerInvariant();var c=Database.Query("SELECT Id,FullName,City,PrimarySkill,ExperienceYears,Education FROM Candidates");var r=new DataTable();r.Columns.Add("Id",typeof(int));r.Columns.Add(L.Fa?"کارجو":"Candidate");r.Columns.Add(L.Fa?"مهارت":"Skill");r.Columns.Add(L.Fa?"سابقه":"Experience",typeof(int));r.Columns.Add(L.Fa?"امتیاز تطبیق":"Match %",typeof(int));r.Columns.Add(L.Fa?"دلیل":"Explanation");foreach(DataRow x in c.Rows){int score=20,exp=Convert.ToInt32(x["ExperienceYears"]);string skill=Convert.ToString(x["PrimarySkill"]),cc=Convert.ToString(x["City"]);string why=L.Fa?"پروفایل پایه":"Base profile";if(!string.IsNullOrWhiteSpace(skill)&&text.Contains(skill.ToLowerInvariant())){score+=45;why+=(L.Fa?"، مهارت مرتبط":"; skill match");}if(!string.IsNullOrWhiteSpace(city)&&string.Equals(city,cc,StringComparison.OrdinalIgnoreCase)){score+=20;why+=(L.Fa?"، شهر یکسان":"; same city");}score+=Math.Min(exp*3,15);r.Rows.Add(x["Id"],x["FullName"],skill,exp,Math.Min(score,100),why);}var dv=r.DefaultView;dv.Sort=(L.Fa?"امتیاز تطبیق":"Match %")+" DESC";grid.DataSource=dv;}}}
